package triggers

import (
	"encoding/json"
	"os"
	"testing"
	"time"
)

// The fixture is generated by core/tests/test_cron_seconds_parity.py from the
// real croniter; this file is the Go half of the dual-run comparison.

type cronParityCase struct {
	Expr      string     `json:"expr"`
	Sequences [][]string `json:"sequences"`
}

type cronParityFixture struct {
	Anchors          []string         `json:"anchors"`
	MatchesPerAnchor int              `json:"matches_per_anchor"`
	Cases            []cronParityCase `json:"cases"`
	Invalid          []string         `json:"invalid"`
}

func loadCronParityFixture(t *testing.T) cronParityFixture {
	t.Helper()
	raw, err := os.ReadFile("testdata/cron_seconds_parity.json")
	if err != nil {
		t.Fatalf("read cron parity fixture: %v", err)
	}
	var fixture cronParityFixture
	if err := json.Unmarshal(raw, &fixture); err != nil {
		t.Fatalf("parse cron parity fixture: %v", err)
	}
	return fixture
}

// Parity: core/tests/test_cron_seconds_parity.py::test_fixture_matches_croniter, core/tests/test_cron_seconds_parity.py::test_croniter_seconds_reference_locks_assumptions
func TestCronSecondsParityAgainstCroniter(t *testing.T) {
	fixture := loadCronParityFixture(t)
	if len(fixture.Anchors) < 3 {
		t.Fatalf("fixture has %d anchors, want >= 3", len(fixture.Anchors))
	}
	if len(fixture.Cases) < 20 {
		t.Fatalf("fixture has %d expressions, want >= 20", len(fixture.Cases))
	}

	for _, c := range fixture.Cases {
		if !IsValidCron(c.Expr) {
			t.Errorf("IsValidCron(%q) = false, croniter accepts it", c.Expr)
			continue
		}
		for anchorIndex, anchorISO := range fixture.Anchors {
			anchor := ParseISO(&anchorISO)
			if anchor == nil {
				t.Fatalf("fixture anchor not parseable: %q", anchorISO)
			}
			want := c.Sequences[anchorIndex]
			if len(want) != fixture.MatchesPerAnchor {
				t.Fatalf("fixture %q anchor %d has %d matches, want %d", c.Expr, anchorIndex, len(want), fixture.MatchesPerAnchor)
			}
			cursor := *anchor
			for step, expected := range want {
				got, ok := NextCronMatch(c.Expr, cursor)
				if !ok {
					t.Errorf("NextCronMatch(%q, %s) step %d = no match, want %s", c.Expr, FormatISO(cursor), step, expected)
					break
				}
				if gotISO := FormatISO(got); gotISO != expected {
					t.Errorf("NextCronMatch(%q, %s) step %d = %s, croniter says %s", c.Expr, FormatISO(cursor), step, gotISO, expected)
				}
				cursor = got
			}
		}
	}
}

// Parity: core/tests/test_cron_seconds_parity.py::test_invalid_cron_corpus_rejected_by_croniter
func TestCronInvalidCorpusParityAgainstCroniter(t *testing.T) {
	fixture := loadCronParityFixture(t)
	if len(fixture.Invalid) < 20 {
		t.Fatalf("fixture has %d invalid expressions, want >= 20", len(fixture.Invalid))
	}
	for _, expr := range fixture.Invalid {
		if IsValidCron(expr) {
			t.Errorf("IsValidCron(%q) = true, croniter rejects it", expr)
		}
	}
}

// Parity: core/tests/test_cron_seconds_parity.py::test_compute_missed_cron_seconds_counts_and_ticks
func TestMissedCronSecondsCountsAndTicks(t *testing.T) {
	since := time.Date(2026, time.May, 18, 9, 0, 0, 0, time.UTC)
	now := time.Date(2026, time.May, 18, 9, 0, 17, 0, time.UTC)
	count, ticks, next := missedForCron("* * * * * */5", since, now)
	if count != 3 {
		t.Fatalf("count = %d, want 3", count)
	}
	wantTicks := []string{
		"2026-05-18T09:00:05+00:00",
		"2026-05-18T09:00:10+00:00",
		"2026-05-18T09:00:15+00:00",
	}
	if !equalStrings(ticks, wantTicks) {
		t.Fatalf("ticks = %v, want %v", ticks, wantTicks)
	}
	requireNextDue(t, next, "2026-05-18T09:00:20+00:00")
}

// Parity: core/tests/test_cron_seconds_parity.py::test_compute_missed_cron_seconds_crosses_minute_boundary
func TestMissedCronSecondsCrossesMinuteBoundary(t *testing.T) {
	since := time.Date(2026, time.May, 18, 9, 0, 55, 0, time.UTC)
	now := time.Date(2026, time.May, 18, 9, 1, 10, 0, time.UTC)
	count, ticks, next := missedForCron("* * * * * */5", since, now)
	if count != 3 {
		t.Fatalf("count = %d, want 3", count)
	}
	wantTicks := []string{
		"2026-05-18T09:01:00+00:00",
		"2026-05-18T09:01:05+00:00",
		"2026-05-18T09:01:10+00:00",
	}
	if !equalStrings(ticks, wantTicks) {
		t.Fatalf("ticks = %v, want %v", ticks, wantTicks)
	}
	requireNextDue(t, next, "2026-05-18T09:01:15+00:00")
}

// Parity: core/tests/test_cron_seconds_parity.py::test_compute_missed_cron_seconds_caps_ticks_at_100
func TestMissedCronSecondsCapsTicksAt100(t *testing.T) {
	since := time.Date(2026, time.May, 18, 9, 0, 0, 0, time.UTC)
	now := time.Date(2026, time.May, 18, 9, 10, 0, 0, time.UTC)
	count, ticks, next := missedForCron("* * * * * */5", since, now)
	if count != 120 {
		t.Fatalf("count = %d, want 120", count)
	}
	if len(ticks) != MaxReportedTicks {
		t.Fatalf("len(ticks) = %d, want %d", len(ticks), MaxReportedTicks)
	}
	if ticks[0] != "2026-05-18T09:00:05+00:00" || ticks[len(ticks)-1] != "2026-05-18T09:08:20+00:00" {
		t.Fatalf("ticks bounds = %s..%s, want 09:00:05..09:08:20", ticks[0], ticks[len(ticks)-1])
	}
	requireNextDue(t, next, "2026-05-18T09:10:05+00:00")
}

// Parity: core/tests/test_cron_seconds_parity.py::test_croniter_seconds_reference_locks_assumptions
func TestNextCronMatchSixFieldLayoutAndBoundaries(t *testing.T) {
	anchor := time.Date(2026, time.May, 18, 9, 0, 0, 0, time.UTC)
	next, ok := NextCronMatch("0 9 * * * 30", anchor)
	if !ok || FormatISO(next) != "2026-05-18T09:00:30+00:00" {
		t.Fatalf("fixed-second match = %v (ok=%v), want 2026-05-18T09:00:30+00:00", FormatISO(next), ok)
	}

	// A seconds step rolls over minute, hour and day boundaries like croniter.
	cursor := time.Date(2026, time.May, 18, 23, 59, 50, 0, time.UTC)
	want := []string{
		"2026-05-18T23:59:55+00:00",
		"2026-05-19T00:00:00+00:00",
		"2026-05-19T00:00:05+00:00",
	}
	for _, expected := range want {
		got, ok := NextCronMatch("* * * * * */5", cursor)
		if !ok || FormatISO(got) != expected {
			t.Fatalf("step match = %s (ok=%v), want %s", FormatISO(got), ok, expected)
		}
		cursor = got
	}

	// Sub-second anchors are floored, and the next match is strictly after.
	micro := time.Date(2026, time.May, 18, 9, 0, 0, 500000, time.UTC)
	got, ok := NextCronMatch("* * * * * *", micro)
	if !ok || FormatISO(got) != "2026-05-18T09:00:01+00:00" {
		t.Fatalf("every-second match = %s (ok=%v), want 2026-05-18T09:00:01+00:00", FormatISO(got), ok)
	}
	got, ok = NextCronMatch("* * * * *", micro)
	if !ok || FormatISO(got) != "2026-05-18T09:01:00+00:00" {
		t.Fatalf("5-field match = %s (ok=%v), want 2026-05-18T09:01:00+00:00", FormatISO(got), ok)
	}
}

func equalStrings(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}
